// Read .env.test and POST to documentation wiki
const fs = require('fs');

// Read and parse .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables, ignoring comments
const envVars = {};
envContent.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    const value = valueParts.join('=');
    if (key && value) {
      envVars[key] = value;
    }
  }
});

// Log the parsed values (for verification)
console.log('Parsed environment variables:', JSON.stringify(envVars, null, 2));

// POST to the documentation wiki endpoint
fetch('http://localhost:3003/api/doc-export', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
  },
  body: JSON.stringify(envVars)
})
  .then(response => {
    console.log('Response status:', response.status);
    return response.text();
  })
  .then(data => {
    console.log('Response body:', data);
  })
  .catch(error => {
    console.error('Error:', error.message);
  });

